/* Flash cards USMLE: Respiratory (455 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["respiratory"] = [{"name":"Anatomy","cards":[["1h25wap1r","What is the conducting zone of the respiratory tree?","Nose, pharynx, larynx, trachea, bronchi, bronchioles, terminal bronchioles; warms, humidifies, filters air; anatomic dead space.","Zona de condução; espaço morto anatômico."],["78dygw1dr","Where do cartilage and goblet cells end in the airways?","Extend to the end of the bronchi.","Até o fim dos brônquios."],["17ttxcl15","Where does pseudostratified ciliated columnar epithelium extend?","To the beginning of terminal bronchioles, then transitions to cuboidal cells.","Até o início dos bronquíolos terminais."],["194wsd61x","Where does airway smooth muscle extend?","To the end of terminal bronchioles (sparse beyond).","Até os bronquíolos terminais."],["1b1sdir1a","What is the respiratory zone?","Respiratory bronchioles, alveolar ducts, alveoli; site of gas exchange.","Zona de troca gasosa."],["1g0937j9a","What is the role of club (Clara) cells?","Nonciliated secretory cells in bronchioles: secrete uteroglobin, GAGs, degrade toxins (CYP450), act as reserve cells.","Células secretoras dos bronquíolos."],["1err1czzq","What are type I pneumocytes?","Squamous cells covering 97% of alveolar surface; thin for gas diffusion.","Pneumócitos I para troca gasosa."],["c3nnwqqi2","What are type II pneumocytes?","Cuboidal cells that secrete surfactant and proliferate to repair damaged alveoli (precursors of type I).","Produzem surfactante e regeneram."],["hcal0y1g9","What are alveolar macrophages?","Phagocytose foreign material; release cytokines; hemosiderin-laden (heart failure cells) in congestion.","Macrófagos alveolares."],["8ugepqitw","What are the lobes of each lung?","Right: 3 lobes (upper, middle, lower). Left: 2 lobes (upper with lingula, lower).","Direito 3, esquerdo 2."],["1hgin7s1h","Why is the right lung more common for aspiration?","Right main bronchus is wider, shorter, and more vertical.","Brônquio direito mais vertical."],["k367eseta","Where does aspirated material go when upright vs supine?","Upright: lower portion of right lower lobe. Supine: superior segment of right lower lobe or posterior segment of right upper lobe.","Depende da posição."],["1pjkmx2lz","What is the relationship of the pulmonary artery to the bronchus at the hilum?","Right: pulmonary artery anterior to bronchus. Left: pulmonary artery superior to bronchus (RALS).","Relação artéria-brônquio no hilo."],["duj894ed4","What structures perforate the diaphragm and at which levels?","IVC at T8, esophagus and vagus at T10, aorta, thoracic duct, azygos at T12 (I 8 10 Eggs At 12).","Aberturas do diafragma."],["101q7lb79","What innervates the diaphragm?","Phrenic nerve (C3-C5); diaphragm irritation refers pain to the shoulder.","Nervo frênico C3-C5."],["wo6qey68c","What are the muscles of quiet inspiration?","Diaphragm.","Diafragma."],["vx1y4msuu","What are the accessory muscles of inspiration?","External intercostals, scalenes, sternocleidomastoids.","Intercostais externos e escalenos."],["wj6dab1t0","What are the muscles of active expiration?","Rectus abdominis, internal and external obliques, transversus abdominis, internal intercostals.","Abdominais e intercostais internos."],["onlzal1d3","Is quiet expiration active or passive?","Passive (elastic recoil).","Passiva."],["156vcm617","What is the bifurcation level of the trachea (carina)?","T4-T5 (sternal angle).","Ângulo esternal."],["7ys6oa1nt","What is the bronchopulmonary segment?","Functional unit supplied by a segmental bronchus and pulmonary artery branch; can be surgically resected.","Segmento broncopulmonar."],["y8ou798mo","What is the dual blood supply of the lungs?","Pulmonary arteries (deoxygenated, for gas exchange) and bronchial arteries (oxygenated, from aorta, nourish airways).","Circulação pulmonar e brônquica."],["1ptlmwtdb","Why is lung infarction uncommon after PE in healthy people?","Dual blood supply from bronchial arteries.","Dupla irrigação."],["tmnruir8t","Where does bronchial venous blood drain?","Partly into pulmonary veins (physiologic shunt), partly into azygos system.","Parte para as veias pulmonares."],["15ils4cgv","What are the pleural layers?","Visceral pleura (on lung, no pain fibers) and parietal pleura (chest wall, sensitive to pain, intercostal and phrenic nerves).","Visceral e parietal."],["ftj4jzd76","Where should a chest tube or thoracentesis needle be inserted?","Above the upper border of the rib to avoid the intercostal neurovascular bundle (VAN below the rib).","Na borda superior da costela."],["x3k2u81yt","Where is the safe triangle for chest tube insertion?","4th-5th intercostal space at the midaxillary line (bounded by pectoralis major, latissimus dorsi, and 5th intercostal space).","Triângulo de segurança."],["1mf1acv4i","What are the pleural reflections at the midclavicular, midaxillary, and paravertebral lines?","Lung inferior border: 6th, 8th, 10th ribs. Pleura: 8th, 10th, 12th ribs.","Limites pulmonares e pleurais."],["51hpfx1oe","What is the location of the horizontal fissure of the right lung?","4th rib (anteriorly).","Quarta costela."],["1spsf3kfl","Where is the oblique fissure?","From T3 spinous process posteriorly to 6th rib anteriorly.","De T3 até a 6ª costela."],["1jyb9xjeb","Where is the right middle lobe heard best?","Anteriorly at the right lower chest near the sternum.","Anteriormente à direita."],["kds4mg1hf","Where are lower lobes best auscultated?","Posteriorly.","Posteriormente."],["1wx53x8jq","What is the larynx's cartilage that is a complete ring?","Cricoid cartilage.","Cricoide."],["1gehjkv1b","Where is a cricothyrotomy performed?","Through the cricothyroid membrane between thyroid and cricoid cartilages.","Membrana cricotireóidea."],["9y81nl10o","What is the narrowest part of the pediatric airway?","Subglottis at the cricoid ring (historically taught).","Região subglótica."],["ham95s15p","What muscle abducts the vocal cords?","Posterior cricoarytenoid.","Cricoaritenoide posterior."],["1xqwx0x1h","What is the epiglottis's role?","Covers the larynx during swallowing to prevent aspiration.","Protege a laringe na deglutição."],["wlfjho1v6","What nerve gives sensation above vs below the vocal cords?","Above: internal laryngeal (superior laryngeal branch). Below: recurrent laryngeal.","Laríngeo interno e recorrente."],["17om4jsm7","What are the paranasal sinuses?","Frontal, maxillary, ethmoid, sphenoid; maxillary most commonly infected in adults.","Seios paranasais."],["1ruzmww1h","Where does the maxillary sinus drain and why is drainage poor?","Middle meatus; ostium is high on the medial wall (poor gravity drainage).","Óstio alto."],["u4vuizxdh","What is Kiesselbach plexus?","Anterior nasal septum vascular plexus; most common site of epistaxis.","Local mais comum de epistaxe."],["1s63ymd1h","Where does life-threatening posterior epistaxis come from?","Sphenopalatine artery (branch of maxillary artery).","Artéria esfenopalatina."],["kyv74fhw2","What drains into the inferior meatus?","Nasolacrimal duct.","Ducto nasolacrimal."],["14wxgiyl1","What is the role of nasal turbinates?","Increase surface area to warm and humidify air.","Aquecem e umidificam o ar."],["1nsfhus12","What is the mediastinum's anterior compartment's common masses?","Thymoma, teratoma, thyroid (retrosternal), lymphoma (4 Ts).","Os 4 Ts."],["i6lpj518m","What is the middle mediastinum's common masses?","Lymphadenopathy, bronchogenic cyst, esophageal tumors, hiatal hernia, aortic aneurysm.","Linfonodos e cistos."],["xe8xzr15y","What is the posterior mediastinum's common masses?","Neurogenic tumors (schwannoma, neuroblastoma), multiple myeloma.","Tumores neurogênicos."],["dojmng1ws","What is the lymphatic drainage of the lungs?","Pulmonary and bronchopulmonary nodes, hilar, tracheobronchial, paratracheal; left lower lobe can drain to right.","Linfonodos hilares e mediastinais."],["exk3nr1m3","Which nerve travels along the pericardium and may be injured in lung surgery?","Phrenic nerve.","Nervo frênico."],["1mivbri1n","What is the azygos lobe?","Anatomic variant where the azygos vein creates an accessory fissure in the right upper lobe.","Variação anatômica."],["1o0kerm1e","What is the role of the cough reflex afferent nerve?","Vagus nerve (internal laryngeal and bronchial receptors).","Nervo vago."],["qtd9g1xak","What is the anatomical dead space volume?","About 150 mL (1 mL per pound of body weight).","Cerca de 150 mL."],["ki0ovhl5j","What is the location of the right recurrent laryngeal nerve?","Loops around the right subclavian artery.","Contorna a subclávia direita."],["19t9m1i12","What tumor at the lung apex compresses the brachial plexus and sympathetic chain?","Pancoast (superior sulcus) tumor.","Tumor de Pancoast."],["3il77yz4e","What is the bronchial tree's generation where gas exchange begins?","Respiratory bronchioles (about generation 17).","Bronquíolos respiratórios."],["9a0c2riac","What is the pores of Kohn?","Interalveolar connections allowing collateral ventilation (and spread of infection).","Comunicações entre alvéolos."],["wt152n19m","What is the role of mucociliary clearance?","Cilia move mucus with trapped particles upward; impaired by smoking and primary ciliary dyskinesia.","Limpeza pelos cílios."],["1d50rsc90","What is the location of the thymus relative to the heart?","Anterior superior mediastinum, anterior to great vessels.","Mediastino anterior."],["1qph2mg1b","What structures pass anterior to the trachea in the neck?","Thyroid isthmus (rings 2-4), inferior thyroid veins; relevant for tracheostomy.","Istmo da tireoide."],["163w7xx1u","What causes paralysis of the left hemidiaphragm after cardiac surgery?","Phrenic nerve injury (cold cardioplegia or direct trauma).","Lesão do frênico."]]},{"name":"Pathology","cards":[["15e7l4d1b","What is rhinosinusitis?","Inflammation of nasal and sinus mucosa, usually viral; bacterial if symptoms >10 days, worsening, or severe (S. pneumoniae, H. influenzae, M. catarrhalis).","Rinossinusite; maioria viral."],["i4n6451pw","What is nasal polyposis associated with?","Chronic rhinosinusitis, asthma, aspirin-exacerbated respiratory disease, cystic fibrosis (in children).","Asma, aspirina e fibrose cística."],["6rpqu2mm0","What is juvenile nasopharyngeal angiofibroma?","Benign vascular tumor in adolescent males causing profuse epistaxis.","Tumor vascular em meninos."],["1rktj3j1m","What is nasopharyngeal carcinoma associated with?","EBV; common in Asian and African populations; cervical lymphadenopathy.","Ligado ao EBV."],["1qsgeesz3","What is laryngeal papillomatosis?","Benign HPV 6/11 papillomas of vocal cords causing hoarseness.","Papilomas por HPV."],["oots6w19d","What is laryngeal carcinoma's main risk factors?","Smoking and alcohol; squamous cell carcinoma; hoarseness.","Tabaco e álcool; rouquidão."],["1iz45sag2","What is a deep venous thrombosis's risk factors?","Virchow triad: stasis (immobility), hypercoagulability (cancer, OCPs, pregnancy, thrombophilia), endothelial damage (surgery, trauma).","Tríade de Virchow."],["s8un8d105","What is the presentation of pulmonary embolism?","Sudden dyspnea, pleuritic chest pain, tachypnea, tachycardia, hypoxemia, hemoptysis; may cause syncope or shock.","Dispneia súbita e dor pleurítica."],["1tfz8lp19","What is the most common ECG finding in PE?","Sinus tachycardia (S1Q3T3 is classic but uncommon).","Taquicardia sinusal."],["wlanhn17a","What is the imaging test of choice for PE?","CT pulmonary angiography (V/Q scan if contrast contraindicated).","Angiotomografia."],["1j5i781km","When is D-dimer useful in PE?","To rule out PE in low pretest probability patients (high sensitivity).","Excluir em baixa probabilidade."],["1g0ghj81s","What are types of emboli?","Fat (long bone fractures, liposuction: hypoxemia, neurologic changes, petechial rash), air, thrombus, bacteria, amniotic fluid, tumor (FAT BAT).","Tipos de êmbolos."],["lf8c8bqfk","What is the treatment of PE?","Anticoagulation (heparin, DOACs); thrombolysis for massive PE with hypotension; IVC filter if anticoagulation contraindicated.","Anticoagulação; trombólise se instável."],["5vcdjzpph","What is a saddle embolus?","Large thrombus at the bifurcation of the pulmonary artery causing sudden death.","Êmbolo em sela."],["1akahv74f","What is the definition of obstructive lung disease?","Obstruction of airflow causing air trapping: FEV1/FVC decreased.","Obstrução ao fluxo."],["9dwn8l1ox","What is chronic bronchitis?","Productive cough for ≥3 months in each of 2 consecutive years; hypertrophy of mucus glands (Reid index >50%); blue bloater.","Tosse produtiva crônica."],["5vdq9j8dv","What is the Reid index?","Ratio of gland layer thickness to bronchial wall thickness; >50% in chronic bronchitis.","Índice de Reid."],["11xhs7th0","What is emphysema?","Enlargement of air spaces with decreased recoil from destruction of alveolar walls; increased compliance; pink puffer.","Destruição dos alvéolos."],["1r727oo1d","What is centriacinar emphysema?","Associated with smoking; upper lobes.","Centroacinar; tabagismo."],["vbytf418p","What is panacinar emphysema?","Associated with alpha-1 antitrypsin deficiency; lower lobes.","Panacinar; deficiência de alfa-1."],["nj9bhn1h3","What is the pathogenesis of emphysema?","Imbalance of proteases (elastase from neutrophils and macrophages) and antiproteases (alpha-1 antitrypsin).","Excesso de elastase."],["1utr1tytl","What are the clinical features of COPD?","Dyspnea, chronic cough, wheezing, prolonged expiration, barrel chest, pursed lip breathing, hypoxemia, hypercapnia in advanced disease.","Dispneia e tosse crônica."],["afqn7y12n","What are complications of COPD?","Cor pulmonale, pneumothorax (bullae), polycythemia, respiratory failure, exacerbations.","Cor pulmonale."],["kpec2t4c3","What interventions reduce mortality in COPD?","Smoking cessation and long-term oxygen therapy (if PaO2 ≤55 or SaO2 ≤88%).","Parar de fumar e oxigênio."],["v6h01bymj","What is the treatment of COPD exacerbation?","Bronchodilators, systemic steroids, antibiotics (if purulent sputum), oxygen (target 88-92%), noninvasive ventilation.","Broncodilatador, corticoide, antibiótico."],["7u4edk11h","What is asthma?","Bronchial hyperresponsiveness causing reversible bronchoconstriction; smooth muscle hypertrophy, goblet cell metaplasia, Curschmann spirals, Charcot-Leyden crystals.","Broncoconstrição reversível."],["2d5u409nd","What are Curschmann spirals?","Shed epithelium forming whorled mucus plugs in asthma.","Espirais de Curschmann."],["1bd1uedd4","What are Charcot-Leyden crystals?","Eosinophilic hexagonal crystals from eosinophil breakdown in asthma.","Cristais de Charcot-Leyden."],["9wfgti19l","What are triggers of asthma?","Allergens, viral URIs, exercise, cold air, stress, aspirin/NSAIDs, smoke.","Alérgenos, vírus, exercício."],["1grfboo1t","What are signs of severe asthma exacerbation?","Inability to speak, silent chest, pulsus paradoxus, normal or high PaCO2, accessory muscle use.","Tórax silencioso e CO2 normal."],["17wl8w81f","What is the pathophysiology of allergic asthma?","Th2 response: IL-4 (IgE), IL-5 (eosinophils), IL-13 (mucus); mast cell degranulation; early and late phase.","Resposta Th2."],["9akmlf1c3","What is bronchiectasis?","Chronic necrotizing infection causing permanently dilated airways: purulent sputum, recurrent infections, hemoptysis, digital clubbing.","Brônquios dilatados permanentemente."],["1cgy7m5di","What are the causes of bronchiectasis?","Cystic fibrosis, primary ciliary dyskinesia, bronchial obstruction, ABPA, prior infection (TB), immunodeficiency.","Fibrose cística e discinesia ciliar."],["18fylti1n","What is allergic bronchopulmonary aspergillosis?","Hypersensitivity to Aspergillus in asthma or CF: central bronchiectasis, eosinophilia, high IgE, mucus plugs.","Aspergilose broncopulmonar alérgica."],["vjgbn41hd","What is restrictive lung disease?","Restricted lung expansion with decreased lung volumes; FEV1/FVC normal or increased.","Restrição à expansão."],["1r4ux00v1","What is idiopathic pulmonary fibrosis?","Progressive fibrosis in older men (smoking, repeated injury, TGF-beta): dry cough, dyspnea, velcro crackles, clubbing; honeycomb lung on CT (subpleural, lower lobes); usual interstitial pneumonia pattern.","Fibrose idiopática; favo de mel."],["6evsa519b","Treatment of idiopathic pulmonary fibrosis?","Antifibrotics (pirfenidone, nintedanib); lung transplant.","Pirfenidona e nintedanibe."],["s1c28kr46","What is hypersensitivity pneumonitis?","Mixed type III/IV reaction to environmental antigens (farmer's lung, bird fancier's): dyspnea, cough, fever, noncaseating granulomas; avoid exposure.","Pneumonite por antígenos ambientais."],["1enfrtr5q","What is sarcoidosis's lung presentation?","Bilateral hilar lymphadenopathy, reticular opacities, noncaseating granulomas; restrictive disease.","Adenopatia hilar bilateral."],["m5y9nqsga","What is eosinophilic pneumonia?","Eosinophilic infiltrates: acute (smoking, drugs) or chronic; Löffler syndrome (parasites).","Pneumonia eosinofílica."],["6yvs3n107","What is cryptogenic organizing pneumonia?","Inflammatory process with granulation tissue plugs in alveoli (Masson bodies); responds to steroids.","Pneumonia em organização."],["1qfvu4n1a","Which drugs cause pulmonary fibrosis?","Methotrexate, nitrofurantoin, amiodarone, bleomycin, busulfan, carmustine.","Metotrexato, amiodarona, bleomicina."],["1nwx53c28","What is coal workers' pneumoconiosis?","Prolonged coal dust exposure: macrophages laden with carbon, upper lobes; progressive massive fibrosis; Caplan syndrome with RA.","Pneumoconiose do carvão."],["sfrafj1k4","What is anthracosis?","Asymptomatic carbon deposition in urban dwellers.","Antracose."],["6yceog14j","What is silicosis?","Foundries, sandblasting, mines: macrophages respond to silica, releasing fibrogenic factors; upper lobes; eggshell calcification of hilar nodes; increased TB risk.","Silicose; risco de tuberculose."],["1yaxe16zz","Why does silicosis increase TB risk?","Silica impairs phagolysosome formation in macrophages.","Sílica prejudica macrófagos."],["1mtk926u1","What is asbestosis?","Shipbuilding, roofing, plumbing: lower lobe fibrosis, calcified pleural plaques (pathognomonic of exposure), ferruginous bodies; increased bronchogenic carcinoma and mesothelioma.","Placas pleurais e corpos ferruginosos."],["1nmde3j9d","What is the most common cancer associated with asbestos?","Bronchogenic carcinoma (especially with smoking), more than mesothelioma.","Carcinoma broncogênico."],["1kqep611d","What is berylliosis?","Aerospace and manufacturing exposure: noncaseating granulomas like sarcoidosis; upper lobes; responds to steroids.","Granulomas como sarcoidose."],["wn4ofi1v2","What is ARDS?","Diffuse alveolar damage from sepsis, aspiration, pneumonia, trauma, pancreatitis: bilateral infiltrates, hypoxemia (PaO2/FiO2 ≤300), not cardiac in origin; hyaline membranes.","Lesão alveolar difusa."],["158brfgek","What is the pathogenesis of ARDS?","Neutrophil-mediated alveolar capillary damage, protein-rich leakage, hyaline membranes, impaired surfactant; later fibrosis.","Dano por neutrófilos."],["v7uu4ahf6","What is the treatment of ARDS?","Treat cause, low tidal volume ventilation, PEEP, prone positioning, conservative fluids.","Ventilação protetora."],["1axrxcpb5","What is cardiogenic pulmonary edema?","Increased pulmonary capillary pressure (left heart failure): PCWP >18, heart failure cells.","Edema por insuficiência cardíaca."],["gta6d21nk","What is noncardiogenic pulmonary edema?","Capillary leak (ARDS, high altitude, neurogenic): normal PCWP.","Edema com pressão capilar normal."],["1vuwu8tin","What is pulmonary hypertension's WHO group 1?","Pulmonary arterial hypertension: idiopathic, BMPR2 mutation, drugs (amphetamines, fenfluramine), connective tissue disease, HIV, portal hypertension, congenital shunts.","Hipertensão arterial pulmonar."],["v6nuz21s0","What is pulmonary hypertension's group 2?","Left heart disease.","Doença cardíaca esquerda."],["v6nuzz1s0","What is pulmonary hypertension's group 3?","Lung diseases and hypoxia (COPD, ILD, OSA, altitude).","Doença pulmonar e hipóxia."],["v6nv481s0","What is pulmonary hypertension's group 4?","Chronic thromboembolic pulmonary hypertension.","Tromboembólica crônica."],["h030avkp0","What is the histology of pulmonary arterial hypertension?","Arteriosclerosis, medial hypertrophy, intimal fibrosis, plexiform lesions.","Lesões plexiformes."],["15pjfte88","What are signs of pulmonary hypertension?","Dyspnea, loud P2, right heart failure (JVD, edema), tricuspid regurgitation.","P2 hiperfonética e falência direita."],["7645o91f9","What is pleural effusion caused by malignancy?","Exudative, often bloody; lung, breast cancer, lymphoma, mesothelioma.","Derrame neoplásico."],["14e3o751q","What is mesothelioma?","Malignancy of the pleura from asbestos: hemorrhagic pleural effusion, pleural thickening; psammoma bodies; calretinin and cytokeratin positive.","Tumor pleural por asbesto."],["fcpco51ci","What is the most common lung cancer in nonsmokers?","Adenocarcinoma.","Adenocarcinoma."],["1co92nndv","What is the leading cause of cancer death?","Lung cancer.","Câncer de pulmão."],["7t5mimzh3","What is the lung cancer screening recommendation?","Annual low-dose CT for ages 50-80 with ≥20 pack-year smoking history, current or quit within 15 years.","Tomografia anual de baixa dose."],["d47h2s1v3","What is small cell lung carcinoma?","Central, very aggressive, smoking-related; neuroendocrine Kulchitsky cells (small dark blue cells); chromogranin, synaptophysin, NSE positive; paraneoplastic syndromes; L-myc.","Pequenas células, central e agressivo."],["1bi3y91nd","What paraneoplastic syndromes occur in small cell carcinoma?","ACTH (Cushing), ADH (SIADH), Lambert-Eaton (anti-calcium channel), paraneoplastic cerebellar degeneration, encephalomyelitis (anti-Hu).","Cushing, SIADH, Lambert-Eaton."],["1hx53vk15","What is the treatment of small cell lung carcinoma?","Chemotherapy and radiation (usually not surgical).","Quimioterapia e radioterapia."],["em3a4ctm7","What is adenocarcinoma of the lung?","Peripheral, most common lung cancer; glandular, mucin-producing; KRAS, EGFR, ALK mutations; associated with hypertrophic osteoarthropathy.","Periférico, mais comum."],["liieqs1aj","What is adenocarcinoma in situ (formerly bronchioloalveolar)?","Grows along alveolar septa (lepidic); ground-glass on CT; better prognosis.","Crescimento lepídico."],["1c5g8qx1r","What is squamous cell carcinoma of the lung?","Central, hilar mass from bronchus, smoking-related; keratin pearls and intercellular bridges; hypercalcemia (PTHrP); cavitation.","Central; PTHrP e hipercalcemia."],["1pwj0jqfn","What is large cell carcinoma of the lung?","Peripheral, poorly differentiated, smoking-related; poor prognosis; may secrete hCG (gynecomastia).","Indiferenciado; prognóstico ruim."],["1ae4hkj94","What is bronchial carcinoid tumor?","Neuroendocrine tumor, often central, polypoid; carcinoid syndrome rare; chromogranin positive; good prognosis; not smoking related.","Tumor carcinoide brônquico."],["obg3px11c","What is the most common lung tumor overall?","Metastases (breast, colon, prostate, bladder): multiple cannonball nodules.","Metástases."],["1pq1reo1o","What are the complications of lung cancer by local spread?","SPHERE: SVC syndrome, Pancoast tumor, Horner syndrome, Endocrine (paraneoplastic), Recurrent laryngeal nerve (hoarseness), Effusions.","Complicações locais."],["1yqo6f71u","What is superior vena cava syndrome?","Obstruction of SVC (lung cancer, lymphoma, thrombosis): facial plethora, arm and face swelling, JVD, headache.","Síndrome da veia cava superior."],["1qji8uw1r","What is a solitary pulmonary nodule's features suggesting malignancy?","Size >8 mm, spiculated margins, growth, upper lobe, smoking history, older age.","Tamanho, espículas e crescimento."],["fd0y2jqj7","What is a lung hamartoma?","Benign coin lesion with cartilage and fat; popcorn calcification.","Hamartoma com calcificação em pipoca."],["a0wcr91et","What is the most common cause of hemoptysis worldwide?","Tuberculosis (in US: bronchitis, bronchiectasis, cancer).","Tuberculose."],["mxb9q1qfm","What is lobar pneumonia's pathology stages?","Congestion (day 1-2), red hepatization (days 3-4), gray hepatization (days 5-7), resolution.","Congestão, hepatização vermelha e cinzenta."],["9ccrqtdph","What is bronchopneumonia?","Patchy infiltrates centered around bronchioles, often multifocal and bilateral (S. aureus, H. influenzae, Klebsiella, S. pyogenes).","Infiltrados irregulares."],["11o3ubkwz","What is interstitial (atypical) pneumonia?","Diffuse patchy inflammation in interstitium; Mycoplasma, Chlamydophila, Legionella, viruses; milder.","Pneumonia intersticial."],["l76a3d1la","What is cryptogenic vs aspiration pneumonia location?","Aspiration: right lower lobe (upright) or posterior upper/superior lower segments (supine); anaerobes.","Aspiração no lobo inferior direito."],["m2x6191ac","What is a lung abscess?","Localized collection of pus, often from aspiration (alcoholics, seizures) with anaerobes, or S. aureus, Klebsiella; air-fluid level; treat with clindamycin.","Abscesso com nível hidroaéreo."],["1mpgkc31c","What is the CURB-65 score?","Confusion, Urea >19, Respiratory rate ≥30, Blood pressure low, age ≥65; guides pneumonia admission.","Gravidade da pneumonia."],["1aathjr1y","What is the empiric treatment of community-acquired pneumonia in an outpatient without comorbidities?","Amoxicillin or doxycycline (macrolide if low resistance).","Amoxicilina ou doxiciclina."],["1iv9mgph5","What is the empiric treatment of community-acquired pneumonia in an outpatient with comorbidities?","Amoxicillin-clavulanate or cephalosporin plus macrolide or doxycycline, or respiratory fluoroquinolone.","Betalactâmico com macrolídeo."],["xl5ap0qr6","What is the presentation of tuberculosis?","Fever, night sweats, weight loss, cough, hemoptysis; apical cavitary lesions in reactivation.","Febre, suor noturno, perda de peso."],["3fkgnhl45","What is the presentation of Pneumocystis pneumonia?","Gradual dyspnea, dry cough, hypoxemia (especially with exertion), bilateral ground-glass in HIV CD4 <200.","Pneumonia em AIDS."],["5qbsf8ge0","What is the presentation of influenza?","Abrupt fever, myalgia, headache, cough; risk of secondary bacterial pneumonia.","Febre súbita e mialgia."],["1b3zyjb1k","What is the presentation of acute bronchitis?","Cough (up to 3 weeks) usually viral; antibiotics not indicated.","Tosse viral; sem antibiótico."],["d3r6581uk","What is croup's presentation and treatment?","Barking cough, inspiratory stridor in young children (parainfluenza); steeple sign; dexamethasone, nebulized epinephrine.","Tosse de cachorro; dexametasona."],["1fo8reg8k","What is epiglottitis's presentation and treatment?","Fever, drooling, dysphagia, tripod position, thumb sign; secure airway, IV antibiotics (ceftriaxone).","Babando; proteger via aérea."],["1bzbnsv1k","What is bronchiolitis's presentation?","Infant with URI then wheezing, crackles, tachypnea (RSV); supportive care.","Sibilância em lactente."],["1g44tgi1p","What is foreign body aspiration's presentation?","Sudden coughing, choking, unilateral wheeze, hyperinflation on expiratory film; bronchoscopy.","Engasgo súbito e sibilo unilateral."],["bi7z4c1v1","What is cystic fibrosis's lung disease?","Thick mucus, recurrent infections (S. aureus, Pseudomonas), bronchiectasis, hemoptysis, nasal polyps.","Muco espesso e bronquiectasia."],["x8i0akw8y","What is alpha-1 antitrypsin deficiency's presentation?","Early-onset panacinar emphysema (lower lobes) in young nonsmokers or smokers; liver cirrhosis.","Enfisema precoce de bases."],["1yxoil31v","What is primary ciliary dyskinesia's lung disease?","Recurrent sinusitis, bronchiectasis, otitis; situs inversus in Kartagener.","Sinusite e bronquiectasia."],["3295k15c3","What is bronchopulmonary dysplasia?","Chronic lung disease in premature infants after prolonged oxygen and ventilation.","Doença pulmonar do prematuro."],["vllhk01fa","What is meconium aspiration syndrome?","Aspiration of meconium-stained fluid causing respiratory distress, pneumothorax, persistent pulmonary hypertension.","Aspiração de mecônio."],["11qz5l21c","What is transient tachypnea of the newborn?","Delayed clearance of fetal lung fluid after C-section; resolves in 24-72 hours.","Taquipneia transitória."],["f6usmdkj6","What is the cause of hemoptysis and glomerulonephritis?","Goodpasture syndrome or granulomatosis with polyangiitis.","Goodpasture ou granulomatose."],["1oqkiwedo","What is diffuse alveolar hemorrhage?","Bleeding into alveoli (vasculitis, Goodpasture, SLE): hemoptysis, anemia, increased DLCO.","Hemorragia alveolar."],["1kdiltip4","What is pulmonary alveolar proteinosis?","Accumulation of surfactant in alveoli from anti-GM-CSF antibodies: crazy paving on CT; whole lung lavage.","Acúmulo de surfactante."],["15xlej215","What is lymphangioleiomyomatosis?","Cystic lung disease in young women (tuberous sclerosis association), pneumothorax, chylothorax.","Doença cística em mulheres jovens."],["9p26eb6yx","What is Langerhans cell histiocytosis of the lung?","Smoking-related nodules and cysts in upper lobes of young adults.","Histiocitose em fumantes."],["1lmnjrr1i","What is the most common cause of chronic cough?","Postnasal drip (upper airway cough syndrome), asthma, GERD, ACE inhibitors.","Gotejamento pós-nasal, asma, refluxo."],["1ipzhf71k","What is the diagnosis of asthma confirmed by?","Spirometry showing reversible obstruction or positive methacholine challenge.","Espirometria com reversibilidade."],["1cusg09xb","What is the classic smoking-related lung lesions besides cancer?","COPD, respiratory bronchiolitis, desquamative interstitial pneumonia, Langerhans cell histiocytosis.","DPOC e bronquiolite respiratória."],["1veuwd5kw","What is the treatment of sarcoidosis?","Steroids if symptomatic or organ-threatening.","Corticoide."],["18iuntdch","What is the cause of bilateral hilar lymphadenopathy in a young Black woman with erythema nodosum?","Sarcoidosis (Löfgren syndrome).","Sarcoidose."],["1utmkou1a","What is high-altitude pulmonary edema?","Noncardiogenic edema from uneven hypoxic vasoconstriction at altitude; treat with descent, oxygen, nifedipine.","Edema de altitude."],["gntirn187","What is reexpansion pulmonary edema?","Edema after rapid reexpansion of collapsed lung (large thoracentesis).","Edema após reexpansão."],["o18wo8nsh","What is neurogenic pulmonary edema?","Edema after severe CNS injury (catecholamine surge).","Edema após lesão cerebral."],["1ks1d2r2t","What is atelectasis's types?","Resorptive (airway obstruction, mediastinum shifts toward), compressive (effusion, shifts away), contraction (fibrosis).","Tipos de atelectasia."],["1utu8421i","What is the most common cause of resorptive atelectasis?","Mucus plug or tumor obstructing a bronchus.","Tampão de muco."],["1ekuyz9ol","What is the presentation of pleuritis?","Sharp pleuritic chest pain worse with inspiration; friction rub.","Dor pleurítica."],["1wgtjs1za","What is the cause of pleural effusion with high amylase?","Pancreatitis or esophageal rupture.","Pancreatite ou ruptura esofágica."],["hluqy112i","What is the cause of pleural effusion with very low glucose?","Rheumatoid arthritis, empyema, malignancy, TB.","Artrite reumatoide e empiema."],["my0x7dkbn","What is the cause of lymphocytic exudative effusion with high adenosine deaminase?","Tuberculous pleuritis.","Tuberculose pleural."],["404e7c12l","What is the most common cause of exudative pleural effusion?","Parapneumonic effusion.","Derrame parapneumônico."],["1oxuu1e1k","What is empyema's treatment?","Chest tube drainage and antibiotics (sometimes surgery or intrapleural fibrinolytics).","Drenagem e antibiótico."],["zxzm951kl","What is the presentation of a Pancoast tumor?","Shoulder and arm pain (brachial plexus), Horner syndrome, hand muscle atrophy.","Dor no ombro e Horner."],["jj324iusp","What is the presentation of recurrent laryngeal nerve compression by lung cancer?","Hoarseness (left side, aortopulmonary window).","Rouquidão."],["85rb1x5kr","What is the lung cancer with highest association with hypercalcemia?","Squamous cell carcinoma (PTHrP).","Carcinoma escamoso."],["mljiql1v2","What is the lung cancer most associated with SIADH and Cushing?","Small cell carcinoma.","Pequenas células."],["puvh831xx","What is the lung cancer associated with gynecomastia?","Large cell carcinoma (hCG).","Grandes células."],["1divyep10","What is the targeted therapy for EGFR-mutant lung adenocarcinoma?","Osimertinib (EGFR tyrosine kinase inhibitors).","Osimertinibe."],["ltrwtju9s","What is the targeted therapy for ALK-rearranged lung cancer?","Alectinib, crizotinib (ALK inhibitors).","Alectinibe."],["f4clr3s53","What is the role of immunotherapy in lung cancer?","PD-1/PD-L1 inhibitors (pembrolizumab) for tumors with high PD-L1 expression.","Pembrolizumabe."],["1rrm7rb6h","What is the cause of COPD in a young nonsmoker with liver disease?","Alpha-1 antitrypsin deficiency.","Deficiência de alfa-1 antitripsina."],["h5s65vvo1","What is the cause of chronic cough in a patient started on lisinopril?","ACE inhibitor-induced cough (bradykinin); switch to ARB.","Tosse por IECA."],["1rzmk7n1w","What is the cause of wheezing and flushing with diarrhea?","Carcinoid syndrome.","Síndrome carcinoide."],["16ai4ezm2","What is the cause of asthma with nasal polyps and aspirin sensitivity?","Aspirin-exacerbated respiratory disease (Samter triad).","Tríade de Samter."],["uwus6udpt","What is the cause of asthma, eosinophilia, and mononeuritis multiplex?","Eosinophilic granulomatosis with polyangiitis (Churg-Strauss).","Churg-Strauss."],["1aemq0t1l","What is the cause of restrictive lung disease with normal DLCO in a patient with ALS?","Neuromuscular weakness (extrapulmonary restriction).","Fraqueza muscular."],["yk21sx148","What is the cause of shortness of breath with pleural plaques in a shipyard worker?","Asbestosis.","Asbestose."],["3x4mi06oh","What is the cause of lung nodules with eggshell calcification of hilar nodes in a sandblaster?","Silicosis.","Silicose."],["1yd1cy21y","What is the cause of noncaseating granulomas in an aerospace engineer?","Berylliosis.","Beriliose."],["kxcay7r6f","What is the cause of fever, cough, and dyspnea in a pigeon breeder?","Hypersensitivity pneumonitis.","Pneumonite de hipersensibilidade."],["ik6zat6sr","What is the cause of sudden dyspnea after a long flight?","Pulmonary embolism.","Embolia pulmonar."],["1q2u97k5n","What is the cause of dyspnea, confusion, and petechiae after a femur fracture?","Fat embolism syndrome.","Embolia gordurosa."],["srpbjr1cm","What is the cause of hypoxemia and DIC during delivery?","Amniotic fluid embolism.","Embolia amniótica."],["12slkelca","What is the cause of decompression sickness?","Nitrogen bubbles forming during rapid ascent from diving: joint pain (bends), neurologic symptoms, dyspnea (chokes); treat with hyperbaric oxygen.","Doença descompressiva."],["1faofb21r","What is the cause of hemoptysis, nasal ulcers, and hematuria?","Granulomatosis with polyangiitis.","Granulomatose com poliangiite."],["zkvky0trh","What is the cause of hypoxemia with clubbing and orthodeoxia in a cirrhotic patient?","Hepatopulmonary syndrome.","Síndrome hepatopulmonar."],["ra924o34b","What is the treatment for anaphylaxis-induced bronchospasm?","IM epinephrine.","Adrenalina intramuscular."],["14si5zl16","What is the hallmark of obstructive sleep apnea diagnosis?","Polysomnography showing apneic episodes (AHI ≥5 with symptoms).","Polissonografia."],["1lmgdf1l5","What is the common pulmonary complication of sickle cell disease?","Acute chest syndrome.","Síndrome torácica aguda."],["vboo0m1ez","What is the cause of recurrent pneumonia in the same location?","Bronchial obstruction (tumor or foreign body).","Obstrução brônquica."],["vrtwf7g7b","What is the cause of recurrent pneumonia in different locations?","Immunodeficiency, aspiration, CF, ciliary dyskinesia.","Imunodeficiência ou aspiração."],["4y667j1vr","What is the hallmark of a pleural transudate?","Low protein and LDH (fails Light criteria).","Proteína e LDH baixas."],["1mx5yhy14","What is the GOLD classification used for in COPD?","Grading airflow limitation by FEV1 % predicted and guiding therapy by symptoms and exacerbations.","Classificação da DPOC."],["4e2ucp1vm","What are the most common triggers of COPD exacerbations?","Viral and bacterial respiratory infections (H. influenzae, S. pneumoniae, M. catarrhalis), air pollution.","Infecções respiratórias."],["1jh19wxlx","What is the chest x-ray in emphysema?","Hyperinflation, flattened diaphragms, increased AP diameter, decreased lung markings, bullae.","Hiperinsuflação."],["1h3astk1n","What is the arterial blood gas in a pink puffer vs blue bloater?","Pink puffer: near-normal PaO2 with hyperventilation. Blue bloater: hypoxemia and hypercapnia.","Soprador rosado versus inchado azul."],["ht6oj9o1p","What is exercise-induced bronchoconstriction treatment?","Inhaled SABA or ICS-formoterol before exercise; montelukast.","Broncodilatador antes do exercício."],["1r5v5tjys","What is the difference between asthma and COPD in reversibility?","Asthma: largely reversible obstruction. COPD: not fully reversible.","Asma reversível; DPOC não."],["1atksdnqi","What is a pulmonary infarct's appearance?","Wedge-shaped hemorrhagic infarct at the periphery (Hampton hump on x-ray).","Infarto em cunha."],["1u4534e1u","What is Westermark sign?","Regional oligemia on chest x-ray in PE.","Oligemia regional."],["16ysezn1c","What is the role of lower extremity ultrasound in suspected PE?","Detects DVT, which supports anticoagulation when CT is not possible.","Detecta trombose venosa."],["l1acr8meb","What is the Wells score used for in PE?","Estimating pretest probability to decide on D-dimer vs imaging.","Probabilidade de embolia."],["1h48oft8s","What is the PERC rule?","Rules out PE without testing in low-risk patients meeting all criteria (age <50, HR <100, SpO2 ≥95%, no hemoptysis, no estrogen, no prior VTE, no unilateral leg swelling, no recent surgery).","Regra PERC."],["d2br7b3hk","What is chronic thromboembolic pulmonary hypertension's treatment?","Pulmonary thromboendarterectomy, riociguat, anticoagulation.","Tromboendarterectomia."],["1008p9ohl","What is the cause of mesothelioma's latency?","Develops decades (20-40 years) after asbestos exposure; smoking does not increase mesothelioma risk.","Décadas após o asbesto."],["13figxnyz","What is the role of bronchoscopy in central lung tumors?","Visualization and biopsy of central lesions (squamous, small cell).","Biópsia de lesões centrais."],["1ubu5ainy","What is the hallmark of acute interstitial pneumonia (Hamman-Rich)?","Idiopathic rapidly progressive ARDS-like illness with diffuse alveolar damage.","SDRA idiopática."],["1djx6mf14","What is nonspecific interstitial pneumonia associated with?","Connective tissue diseases; better prognosis than IPF; responds to steroids.","Doenças do colágeno."],["19kpsfk1t","What is the interstitial lung disease in systemic sclerosis?","Nonspecific interstitial pneumonia (leading cause of death with pulmonary hypertension).","PINE na esclerodermia."],["32ncwn11t","What is the hallmark lung finding in rheumatoid arthritis?","Interstitial lung disease, rheumatoid nodules, pleural effusion with low glucose.","Doença intersticial e nódulos."]]},{"name":"Pharmacology","cards":[["1bt6x4z1i","What are first-generation H1 blockers?","Diphenhydramine, dimenhydrinate, chlorpheniramine, doxylamine, hydroxyzine, meclizine, promethazine.","Anti-histamínicos de primeira geração."],["1jzvsh21a","Uses of first-generation H1 blockers?","Allergy, motion sickness, insomnia, nausea, pruritus.","Alergia, cinetose, insônia."],["tjqbcw1ih","Adverse effects of first-generation H1 blockers?","Sedation, antimuscarinic and anti-alpha-adrenergic effects; avoid in elderly.","Sedação e efeitos anticolinérgicos."],["phoiyx1en","What are second-generation H1 blockers?","Loratadine, fexofenadine, desloratadine, cetirizine (end in -adine or -tirizine).","Anti-histamínicos de segunda geração."],["u99sbaqea","Why are second-generation antihistamines less sedating?","Less entry into the CNS (more polar).","Atravessam menos a barreira."],["lbz6sm3xb","Mechanism and use of guaifenesin?","Expectorant that thins respiratory secretions; does not suppress cough.","Expectorante."],["p8hbhuz94","Mechanism and use of N-acetylcysteine as mucolytic?","Breaks disulfide bonds in mucus; also acetaminophen antidote.","Mucolítico."],["12xqf1mak","Mechanism and use of dornase alfa?","DNase that degrades extracellular DNA in mucus; cystic fibrosis.","Fibrose cística."],["12jutgu19","Mechanism and use of dextromethorphan?","Antagonizes NMDA receptors; antitussive; serotonin syndrome risk with SSRIs; abuse potential.","Antitussígeno."],["tckdn8o4k","Mechanism and use of pseudoephedrine and phenylephrine?","Alpha-adrenergic agonists for nasal decongestion.","Descongestionantes."],["rlzi5n1k4","Adverse effects of decongestants?","Hypertension, rebound congestion (rhinitis medicamentosa) with prolonged topical use; pseudoephedrine illicitly used for methamphetamine.","Hipertensão e efeito rebote."],["1b16lju1j","Mechanism and use of bosentan, ambrisentan, macitentan?","Endothelin receptor antagonists; pulmonary arterial hypertension; hepatotoxic and teratogenic.","Antagonistas da endotelina."],["jq6x68140","Mechanism and use of sildenafil and tadalafil in PAH?","PDE5 inhibitors increasing cGMP, pulmonary vasodilation.","Vasodilatação pulmonar."],["1vaah7i1i","Mechanism and use of prostacyclin analogs in PAH?","Epoprostenol, treprostinil, iloprost: direct vasodilation, inhibit platelet aggregation; flushing, jaw pain.","Prostaciclinas."],["1akibp5ob","Mechanism and use of riociguat?","Soluble guanylate cyclase stimulator; PAH and chronic thromboembolic pulmonary hypertension; contraindicated with PDE5 inhibitors.","Estimula guanilato ciclase."],["13y2k431l","Mechanism and use of short-acting beta2 agonists?","Albuterol, levalbuterol: relax bronchial smooth muscle; acute asthma and COPD symptoms (rescue).","Broncodilatador de resgate."],["1boblcbca","Mechanism and use of long-acting beta2 agonists?","Salmeterol, formoterol, vilanterol, indacaterol: long-acting bronchodilation; maintenance (never as monotherapy in asthma).","Broncodilatador de longa ação."],["1fs4ic11r","Why should LABAs not be used alone in asthma?","Increased risk of asthma-related death; must be combined with inhaled corticosteroids.","Sempre com corticoide inalado."],["13j8bq71o","Adverse effects of beta2 agonists?","Tremor, tachycardia, arrhythmia, hypokalemia.","Tremor, taquicardia, hipocalemia."],["1mtuselav","Mechanism and use of inhaled corticosteroids?","Beclomethasone, budesonide, fluticasone: inhibit cytokine synthesis (NF-kB); first-line long-term asthma control.","Controle da asma."],["f98mko15i","Adverse effects of inhaled corticosteroids?","Oral thrush (rinse mouth), hoarseness; pneumonia risk in COPD.","Candidíase oral."],["b75n5u6tj","Mechanism and use of ipratropium?","Short-acting muscarinic antagonist; COPD, acute asthma adjunct.","Antimuscarínico de curta ação."],["1adefom1x","Mechanism and use of tiotropium, aclidinium, umeclidinium?","Long-acting muscarinic antagonists; COPD maintenance (and asthma add-on).","Antimuscarínicos de longa ação."],["1nrckds6c","Mechanism and use of montelukast and zafirlukast?","Block leukotriene receptors (CysLT1); asthma, especially aspirin-induced and exercise-induced, allergic rhinitis.","Antileucotrienos."],["2cqwcspau","Adverse effects of montelukast?","Neuropsychiatric events (mood changes, suicidality).","Alterações de humor."],["mufkka3uq","Mechanism and use of zileuton?","5-lipoxygenase inhibitor blocking leukotriene synthesis; asthma; hepatotoxic.","Inibe a lipoxigenase."],["1p861itr8","Mechanism and use of theophylline?","Methylxanthine: PDE inhibitor (increased cAMP) and adenosine antagonist; bronchodilation; narrow therapeutic index.","Teofilina; janela estreita."],["nqy87ku28","Adverse effects of theophylline?","Cardiotoxicity (arrhythmias), neurotoxicity (seizures), nausea; metabolized by CYP1A2 (interactions with cimetidine, ciprofloxacin, smoking).","Arritmias e convulsões."],["h94ir018w","Mechanism and use of roflumilast?","PDE4 inhibitor reducing inflammation; severe COPD with chronic bronchitis and exacerbations; weight loss, diarrhea.","Inibidor de PDE4 na DPOC."],["196xpuv1o","Mechanism and use of cromolyn?","Mast cell stabilizer preventing degranulation; prevention of allergic asthma and rhinitis (rarely used).","Estabilizador de mastócitos."],["qe9o3r156","Mechanism and use of omalizumab?","Anti-IgE monoclonal antibody; severe allergic asthma with high IgE, chronic urticaria.","Anti-IgE."],["b6agnhzuy","Mechanism and use of mepolizumab, reslizumab, benralizumab?","Anti-IL-5 (or IL-5 receptor); severe eosinophilic asthma.","Anti-IL-5."],["uqn996146","Mechanism and use of dupilumab in asthma?","Anti-IL-4 receptor alpha (blocks IL-4 and IL-13); eosinophilic asthma, atopic dermatitis.","Bloqueia IL-4 e IL-13."],["10vq7n01o","Mechanism and use of tezepelumab?","Anti-thymic stromal lymphopoietin; severe asthma regardless of phenotype.","Anti-TSLP."],["1x3fxbz1t","Mechanism and use of methacholine?","Muscarinic agonist used in bronchial challenge testing for asthma.","Teste de broncoprovocação."],["1ynf9h019","Mechanism and use of systemic corticosteroids in respiratory disease?","Acute asthma and COPD exacerbations, ABPA, sarcoidosis, organizing pneumonia, PCP with hypoxemia.","Exacerbações graves."],["1ejota21b","What is the stepwise approach in asthma?","Step up from as-needed SABA or low-dose ICS-formoterol to ICS-LABA, higher doses, add LAMA, biologics, oral steroids.","Tratamento em etapas."],["rfsk4d1j6","What is the preferred reliever in modern asthma guidelines?","Low-dose ICS-formoterol (as needed), or SABA with ICS.","ICS-formoterol de resgate."],["1get9fx2b","What is the treatment of acute asthma exacerbation?","Oxygen, inhaled SABA and ipratropium, systemic corticosteroids, IV magnesium if severe, intubation if failing.","Salbutamol, ipratrópio, corticoide, magnésio."],["1xk17q31k","What is the maintenance treatment of COPD?","LAMA and/or LABA; add ICS if frequent exacerbations and eosinophilia; pulmonary rehabilitation; vaccination; smoking cessation.","Broncodilatadores de longa ação."],["1oorifxnl","Which vaccines are recommended in COPD?","Influenza, pneumococcal, COVID-19, Tdap, RSV (older adults).","Gripe e pneumococo."],["zs9ex4136","What is the indication for long-term oxygen in COPD?","PaO2 ≤55 mmHg or SaO2 ≤88%, or PaO2 ≤59 with cor pulmonale or polycythemia.","Saturação ≤88%."],["1t0oo2gjd","What is the antibiotic choice in COPD exacerbation?","Amoxicillin-clavulanate, doxycycline, azithromycin.","Amoxicilina-clavulanato ou doxiciclina."],["1hv9mu814","What is the role of azithromycin in chronic COPD?","Reduces exacerbations (anti-inflammatory) in frequent exacerbators; QT and hearing risks.","Reduz exacerbações."],["1jp8ek7am","What drugs are used for idiopathic pulmonary fibrosis?","Pirfenidone (antifibrotic, TGF-beta inhibition) and nintedanib (tyrosine kinase inhibitor).","Pirfenidona e nintedanibe."],["yxty9g1wb","What drugs are used for CF lung disease?","CFTR modulators (elexacaftor-tezacaftor-ivacaftor), dornase alfa, hypertonic saline, inhaled tobramycin, azithromycin, airway clearance.","Moduladores do CFTR."],["1htkagi1c","What is the mechanism of ivacaftor?","CFTR potentiator increasing chloride channel opening (gating mutations like G551D).","Potencializador do CFTR."],["175x4va1t","What is the mechanism of lumacaftor, tezacaftor, elexacaftor?","CFTR correctors improving protein folding and trafficking (deltaF508).","Corretores do CFTR."],["5t33nja3h","What drug is used for smoking cessation besides nicotine replacement?","Varenicline (most effective) and bupropion.","Vareniclina e bupropiona."],["1fbxarymm","What is the treatment of latent TB?","Rifampin 4 months, isoniazid-rifapentine 3 months weekly, or isoniazid 6-9 months.","Tratamento da TB latente."],["uwkfl0f1x","What is the treatment of active TB?","Rifampin, isoniazid, pyrazinamide, ethambutol for 2 months, then rifampin and isoniazid for 4 months.","Esquema RIPE."],["uf1ac7zm1","What is the treatment of PCP pneumonia?","TMP-SMX (plus steroids if PaO2 <70).","Sulfametoxazol-trimetoprima."],["rrb8omcd5","What is the treatment of influenza?","Oseltamivir or baloxavir within 48 hours (or anytime if hospitalized or high risk).","Oseltamivir."],["1d80yvn19","What is the treatment of PE in a stable patient?","Anticoagulation (DOAC or LMWH then warfarin) for at least 3 months.","Anticoagulação por 3 meses."],["q1hrx3ujg","What is the treatment of PE in pregnancy?","Low-molecular-weight heparin.","Heparina de baixo peso."],["1uobyicnc","What is the treatment of PE in cancer patients?","LMWH or DOACs (apixaban, edoxaban, rivaroxaban).","Heparina ou DOAC."],["c6r8wlnup","What is the treatment of massive PE with hypotension?","Systemic thrombolysis (alteplase) or embolectomy.","Trombólise."],["1nhybge1u","What is the prophylaxis of DVT in hospitalized patients?","LMWH, unfractionated heparin, or fondaparinux; mechanical compression if bleeding risk.","Heparina profilática."],["bqugl01rn","What is the treatment of sarcoidosis requiring steroid-sparing agents?","Methotrexate, azathioprine, infliximab.","Metotrexato."],["12mrj49ex","What is the treatment of high-altitude illness prevention?","Gradual ascent, acetazolamide (and nifedipine for HAPE prevention, dexamethasone for HACE).","Subida gradual e acetazolamida."],["ckybcn657","What is the treatment of acute mountain sickness severe?","Descent, oxygen, dexamethasone.","Descer e oxigênio."],["plcosfjkk","What is the treatment of allergic rhinitis?","Intranasal corticosteroids (most effective), oral or intranasal antihistamines, leukotriene antagonists.","Corticoide nasal."],["1vfipo35d","What is the treatment of nasal polyps in AERD?","Intranasal steroids, aspirin desensitization, dupilumab, surgery.","Corticoide nasal e dupilumabe."],["yqyjvu1xg","What is the treatment of acute bacterial sinusitis?","Amoxicillin-clavulanate (if criteria met).","Amoxicilina-clavulanato."],["trry7h1qu","What drug causes cough by increasing bradykinin?","ACE inhibitors.","IECA."],["tl4tt61el","What drug class can precipitate bronchospasm in asthma?","Nonselective beta-blockers and NSAIDs (in AERD).","Betabloqueadores não seletivos."],["1e6izc1oz","What monitoring is recommended for amiodarone's lung toxicity?","Baseline chest x-ray and pulmonary function tests (DLCO), with evaluation if new dyspnea or cough.","Raio X e prova de função pulmonar."],["11fjqy51n","Which drug causes respiratory depression with benzodiazepines?","Opioids (synergistic).","Opioides."],["pkc2312pt","Which drug reverses opioid-induced respiratory depression?","Naloxone.","Naloxona."],["9nlsnxee6","What is the mechanism of doxapram?","Respiratory stimulant acting on peripheral chemoreceptors (rarely used).","Estimulante respiratório."],["19hw4qclw","What drug is used to treat apnea of prematurity?","Caffeine citrate (adenosine antagonist).","Citrato de cafeína."],["gziq8y1vx","What drug is given antenatally to prevent neonatal RDS?","Betamethasone or dexamethasone.","Corticoide antenatal."],["fbv6s1428","What is given to premature infants with RDS?","Exogenous surfactant and CPAP.","Surfactante exógeno."],["1q9daxkxo","What drug class is used for COVID-19 hypoxemia?","Dexamethasone (and remdesivir, IL-6 or JAK inhibitors in selected cases).","Dexametasona."],["1t9izyl1b","What drug is used for RSV prevention in infants?","Nirsevimab (monoclonal antibody).","Nirsevimabe."],["fr5s6910e","What drug is used for prophylaxis of meningococcal exposure in close contacts?","Rifampin, ciprofloxacin, or ceftriaxone.","Rifampicina ou ciprofloxacino."]]},{"name":"Physiology","cards":[["6tmhti1sb","What is tidal volume?","Air moving into the lung with each quiet inspiration; typically 500 mL.","Volume corrente."],["rfzmb01we","What is inspiratory reserve volume?","Air that can still be breathed in after normal inspiration.","Volume de reserva inspiratório."],["12pa7ph3z","What is expiratory reserve volume?","Air that can still be breathed out after normal expiration.","Volume de reserva expiratório."],["g5eqpf8qw","What is residual volume?","Air in the lung after maximal expiration; cannot be measured by spirometry.","Volume residual."],["71iggg1ru","What is inspiratory capacity?","IRV + TV: air that can be breathed in after normal exhalation.","Capacidade inspiratória."],["1p9f4rku4","What is functional residual capacity?","RV + ERV: volume in lungs after normal expiration; system at equilibrium.","Capacidade residual funcional."],["loxyfs78y","What is vital capacity?","TV + IRV + ERV: maximum volume exhaled after maximal inspiration.","Capacidade vital."],["1duwclo12","What is total lung capacity?","IRV + TV + ERV + RV: volume of gas in lungs after maximal inspiration.","Capacidade pulmonar total."],["fosg2rljw","How are RV, FRC, and TLC measured?","Helium dilution, nitrogen washout, or body plethysmography (spirometry cannot).","Pletismografia ou diluição de hélio."],["cucvv4lte","What is physiologic dead space?","Anatomic dead space plus alveolar dead space (ventilated but not perfused).","Espaço morto fisiológico."],["ni84541ma","What is the Bohr equation?","VD/VT = (PaCO2 - PECO2) / PaCO2.","Fórmula do espaço morto."],["dzm9w516m","What is minute ventilation?","VE = VT x respiratory rate.","Ventilação minuto."],["8or179vq7","What is alveolar ventilation?","VA = (VT - VD) x respiratory rate.","Ventilação alveolar."],["1tf8kw6im","Why is deep slow breathing more efficient than rapid shallow breathing?","Less of each breath is wasted on dead space, increasing alveolar ventilation.","Menos espaço morto por respiração."],["1rsqrfra4","What is lung compliance?","Change in lung volume for a change in pressure; decreased in fibrosis, edema, ARDS; increased in emphysema and aging.","Complacência pulmonar."],["1pk7gb5v1","What is elastic recoil?","Tendency of lungs to collapse inward and chest wall to spring outward; at FRC these are balanced.","Retração elástica."],["1o7005t4k","What is the role of surfactant?","Dipalmitoylphosphatidylcholine reduces alveolar surface tension, preventing collapse and increasing compliance.","Reduz a tensão superficial."],["q7wu49yqs","What is the law of Laplace for alveoli?","Collapsing pressure = 2 x surface tension / radius; small alveoli tend to collapse without surfactant.","Alvéolos pequenos colapsam mais."],["1emd3ji12","What is neonatal respiratory distress syndrome?","Surfactant deficiency in premature infants: increased surface tension, atelectasis, ground-glass on x-ray; risk factors prematurity, maternal diabetes, C-section.","Falta de surfactante no prematuro."],["1ts3t951b","What are complications of oxygen therapy in neonates?","Retinopathy of prematurity, bronchopulmonary dysplasia, intraventricular hemorrhage.","Retinopatia e displasia broncopulmonar."],["1dufq9r1s","What is the hemoglobin structure and O2 binding?","Four subunits (2 alpha, 2 beta), each binding one O2; T (taut, low affinity) and R (relaxed, high affinity) forms.","Quatro subunidades."],["14skbshva","What is the formula for O2 content of blood?","(1.34 x Hb x SaO2) + (0.003 x PaO2).","Conteúdo arterial de oxigênio."],["15ga4nzb5","What is the effect of anemia on PaO2, SaO2, and O2 content?","PaO2 and SaO2 normal; O2 content decreased.","Só o conteúdo cai."],["1nhaugo13","What is the effect of CO poisoning on PaO2, SaO2, and O2 content?","PaO2 normal; true SaO2 decreased (pulse oximetry falsely normal); O2 content decreased.","Saturação real cai."],["3cia0ki21","What is the effect of polycythemia on O2 content?","Increased O2 content; PaO2 and SaO2 normal.","Conteúdo aumenta."],["11ee4cyyp","What is the oxygen-hemoglobin dissociation curve shape and why?","Sigmoidal due to positive cooperativity.","Sigmoide pela cooperatividade."],["1svksa815","What shifts the O2 curve right?","Increased CO2, acid (H+), exercise, 2,3-BPG, altitude, temperature (ACE BATs right handed).","Desvio à direita libera O2."],["do9o40zhs","What is the P50 and what happens in a right shift?","PaO2 at 50% saturation (~26 mmHg); right shift increases P50 (lower affinity).","P50 aumenta."],["udr0ldpck","How is CO2 transported in blood?","As bicarbonate (70%), carbaminohemoglobin (21-25%), dissolved CO2 (5-9%).","Principalmente bicarbonato."],["q6sstd1q3","What is the chloride shift?","HCO3- exits RBCs in exchange for Cl- (band 3) in tissues; reversed in lungs.","Troca cloreto-bicarbonato."],["nmq5547l2","What is the normal PaO2 and PaCO2?","PaO2 75-105 mmHg; PaCO2 35-45 mmHg.","Valores normais."],["reksgkbm3","What is the alveolar gas equation?","PAO2 = FiO2 (Patm - PH2O) - PaCO2/R ≈ 150 - PaCO2/0.8 at sea level.","Equação do gás alveolar."],["f5ug6j1vy","What is the normal A-a gradient?","10-15 mmHg (increases with age: age/4 + 4).","Gradiente A-a normal."],["1hnp6r21j","What causes hypoxemia with normal A-a gradient?","High altitude (low PiO2), hypoventilation (opioids, neuromuscular disease, obesity hypoventilation).","Altitude e hipoventilação."],["17bfoil1v","What causes hypoxemia with increased A-a gradient?","V/Q mismatch, diffusion limitation (fibrosis), right-to-left shunt.","V/Q, difusão e shunt."],["1l94kh167","How do you distinguish V/Q mismatch from shunt?","V/Q mismatch improves with supplemental O2; shunt does not (or minimally).","Shunt não melhora com oxigênio."],["1r5i9ey1l","What is the V/Q ratio at the apex vs base of the lung?","Apex: high V/Q (~3, wasted ventilation). Base: low V/Q (~0.6, wasted perfusion).","Ápice alto; base baixo."],["1a4j54gxw","Why do both ventilation and perfusion increase toward the lung base?","Gravity; perfusion increases more than ventilation.","Gravidade."],["1rpauof1f","What is a V/Q of zero vs infinity?","Zero: airway obstruction (shunt). Infinity: blood flow obstruction (dead space, e.g., PE).","Zero é shunt; infinito é espaço morto."],["1e2bz5w17","Why does TB prefer the lung apex?","High V/Q gives high PaO2 favoring aerobic growth.","Mais oxigênio no ápice."],["1ym9igi19","What is perfusion-limited gas exchange?","O2 (normal health), CO2, N2O: gas equilibrates early; increasing diffusion needs more blood flow.","Limitada pela perfusão."],["1di6numo5","What is diffusion-limited gas exchange?","CO (always), O2 in emphysema, fibrosis, exercise at altitude: gas does not equilibrate by end of capillary.","Limitada pela difusão."],["ltv4zqhwh","Why is carbon monoxide used to measure DLCO?","Its transfer is diffusion-limited, reflecting membrane diffusion capacity.","CO mede a difusão."],["1fr0rdxnr","What decreases DLCO?","Emphysema, interstitial lung disease, pulmonary vascular disease (PE, pulmonary hypertension), anemia.","Enfisema e fibrose."],["grrccjd79","What increases DLCO?","Pulmonary hemorrhage, polycythemia, asthma (sometimes), left-to-right shunt.","Hemorragia pulmonar e policitemia."],["1gzvk6j11","What is the normal pulmonary artery pressure and resistance?","Mean 10-14 mmHg; low resistance, high compliance system.","Baixa pressão e resistência."],["xrmqrm1c7","What is pulmonary hypertension definition?","Mean pulmonary artery pressure >20 mmHg at rest.","Pressão média maior que 20."],["1151dv7cw","What is hypoxic pulmonary vasoconstriction?","Low alveolar O2 causes local vasoconstriction, shifting blood to better-ventilated areas (opposite of systemic vessels).","Vasoconstrição por hipóxia."],["1xcxh9i19","What is the response to high altitude acutely?","Hyperventilation (respiratory alkalosis), increased HR.","Hiperventilação."],["191vpnjff","What are chronic adaptations to high altitude?","Increased EPO and hematocrit, increased 2,3-BPG, renal HCO3- excretion, increased mitochondria, pulmonary vasoconstriction (RV hypertrophy).","Mais eritropoetina e 2,3-BPG."],["fbz5giapf","How does acetazolamide help with altitude sickness?","Causes bicarbonate diuresis and metabolic acidosis, stimulating ventilation.","Estimula a ventilação."],["ge06iq1f0","What are the responses to exercise?","Increased CO2 production, O2 consumption, ventilation rate, V/Q more uniform, pulmonary blood flow increased; PaO2 and PaCO2 normal; venous CO2 increased, venous O2 decreased.","Respostas ao exercício."],["99urzuo4h","What controls breathing centrally?","Medullary respiratory center (dorsal: inspiration; ventral: expiration), pontine apneustic and pneumotaxic centers.","Centro respiratório bulbar."],["oac1qgzr3","What do central chemoreceptors detect?","Changes in pH of CSF from PaCO2 (CO2 crosses BBB); main driver of ventilation.","CO2 via pH do líquor."],["16ujgn1hx","What do peripheral chemoreceptors detect?","Carotid and aortic bodies detect decreased PaO2 (<60 mmHg), increased PaCO2, decreased pH.","Hipóxia, CO2 e pH."],["1etzeb7vf","Why can high-flow O2 worsen hypercapnia in COPD?","Worsened V/Q mismatch (release of hypoxic vasoconstriction), Haldane effect, and reduced hypoxic drive.","Piora o V/Q e o efeito Haldane."],["wy4zo6whw","What is the Hering-Breuer reflex?","Lung stretch receptors (vagus) inhibit inspiration to prevent overinflation.","Reflexo de estiramento."],["zwneyt9dd","What does spirometry show in obstructive disease?","Decreased FEV1, decreased FEV1/FVC (<70%), increased TLC and RV (air trapping).","Relação VEF1/CVF baixa."],["1mtatgj1m","What does spirometry show in restrictive disease?","Decreased TLC, FEV1 and FVC reduced proportionally, normal or increased FEV1/FVC.","Volumes reduzidos e relação normal."],["ntqpd91d4","What is the flow-volume loop in obstruction?","Scooped (concave) expiratory limb.","Curva escavada."],["1n4uzv0bj","What is the flow-volume loop in fixed upper airway obstruction?","Flattening of both inspiratory and expiratory limbs.","Achatamento das duas fases."],["1xtjilj1n","What does bronchodilator reversibility indicate?","Asthma (≥12% and 200 mL increase in FEV1).","Reversibilidade sugere asma."],["8t2ppe1sn","What does a positive methacholine challenge indicate?","Airway hyperreactivity (asthma).","Hiper-reatividade brônquica."],["1cp8i8k12","What is the cause of restrictive lung disease with normal DLCO?","Extrapulmonary (poor breathing mechanics): neuromuscular disease, chest wall deformities (kyphoscoliosis), obesity.","Causa extrapulmonar."],["2ybt9d1ci","What is the cause of restrictive lung disease with decreased DLCO?","Interstitial lung disease (fibrosis).","Doença intersticial."],["y7o9cohvr","What is the effect of obesity on lung volumes?","Decreased ERV and FRC; restrictive pattern.","Reduz ERV e CRF."],["qzyjwy131","What is the effect of emphysema on lung compliance?","Increased compliance (loss of elastic recoil).","Complacência aumentada."],["psb4k814u","What is the effect of fibrosis on lung compliance?","Decreased compliance (stiff lungs).","Complacência reduzida."],["13wctmw15","What is airway resistance's main site?","Medium-sized bronchi.","Brônquios médios."],["1q9he2q1n","What is the effect of lung volume on airway resistance?","Higher lung volume increases radial traction, decreasing resistance.","Volume maior reduz resistência."],["1lj303o1k","What is dynamic airway compression?","During forced expiration, airways compress when intrapleural pressure exceeds airway pressure; worse in emphysema (pursed-lip breathing helps).","Compressão na expiração forçada."],["1j99yxm1y","What is intrapleural pressure normally?","Negative (about -5 cm H2O at FRC).","Negativa."],["1mh6jwfhy","What happens to intrapleural pressure in pneumothorax?","Becomes atmospheric; lung collapses, chest wall springs out.","Fica igual à atmosférica."],["1eowj4fpk","What is the role of 2,3-BPG in fetal oxygen transfer?","HbF binds 2,3-BPG poorly, giving higher O2 affinity to extract O2 from maternal blood.","HbF liga pouco 2,3-BPG."],["1hl950mcd","What is methemoglobin's effect on O2 binding?","Fe3+ cannot bind O2; remaining hemes bind O2 tighter (left shift), decreasing delivery.","Prende O2."],["ey42qo1om","What is the treatment of cyanide poisoning's mechanism with nitrites?","Nitrites oxidize Hb to methemoglobin, which binds cyanide; thiosulfate forms thiocyanate for excretion.","Metemoglobina sequestra cianeto."],["9jr6ns1x5","What is the venous O2 saturation in cyanide poisoning?","High (tissues cannot use O2).","Saturação venosa alta."],["bicb0o16e","What is the cause of cyanosis?","Deoxygenated hemoglobin >5 g/dL in capillaries.","Hemoglobina desoxigenada acima de 5."],["6u7v22plw","Why is cyanosis less visible in anemia?","Insufficient total hemoglobin to reach 5 g/dL deoxygenated.","Pouca hemoglobina."],["22kru2jgr","What is the A-a gradient in PE?","Increased (V/Q mismatch, dead space).","Aumentado."],["gwyido1up","What is the arterial blood gas in acute PE?","Hypoxemia, hypocapnia, respiratory alkalosis.","Hipoxemia e alcalose respiratória."],["tr8ugcsmz","What is the arterial blood gas in acute asthma exacerbation?","Early respiratory alkalosis; normal or rising PaCO2 is ominous (fatigue).","CO2 normal indica fadiga."],["18hoi2ld5","What is the arterial blood gas in chronic COPD with CO2 retention?","Chronic respiratory acidosis with metabolic compensation (high HCO3-).","Acidose respiratória compensada."],["1k16520t5","What is the arterial blood gas in opioid overdose?","Respiratory acidosis with normal A-a gradient.","Acidose respiratória com gradiente normal."],["g9a0i431m","What is the respiratory effect of metabolic acidosis?","Compensatory hyperventilation (Kussmaul).","Hiperventilação de Kussmaul."],["1aymqgnex","What is the respiratory quotient (R)?","CO2 produced / O2 consumed; about 0.8 on a mixed diet; 1.0 for carbohydrate.","Quociente respiratório."],["lif18bohw","What is the work of breathing in obstructive vs restrictive disease?","Obstructive: slow deep breaths minimize resistive work. Restrictive: rapid shallow breaths minimize elastic work.","Padrões respiratórios."],["2mqgtyh6u","What is the effect of supine position on FRC?","Decreases FRC (abdominal contents push diaphragm up).","Deitado reduz CRF."],["768z4nh7j","What is the role of the cough reflex in protecting the lungs?","Expels foreign material; impaired by opioids, sedation, neurologic disease.","Expulsa material estranho."],["1difov6ey","What is the definition of hypoxia vs hypoxemia?","Hypoxemia: low arterial PaO2. Hypoxia: inadequate O2 delivery to tissues.","Hipoxemia é sangue; hipóxia é tecido."],["1e6l16hso","What are causes of hypoxia without hypoxemia?","Anemia, CO poisoning, cyanide poisoning, decreased cardiac output.","Anemia, CO, cianeto."],["1lvskh5mf","What is the role of ventilation in acid-base balance?","Adjusts PaCO2 to compensate for metabolic disturbances within minutes.","Ajusta o CO2."],["19w2wbz1w","What is the Haldane effect?","Oxygenation of Hb in lungs decreases its CO2 affinity, releasing CO2.","Oxigênio libera CO2."],["1kktcojhf","What is the Bohr effect?","Increased CO2 and H+ in tissues decrease Hb affinity for O2, releasing O2.","CO2 libera O2."],["1ciwbhgnj","What is the pulmonary vascular resistance minimum?","At FRC; increases at high and low lung volumes.","Mínima na CRF."],["121tj9a1f","What are West zones of the lung?","Zone 1 (PA > Pa > Pv, no flow, apex in hypotension or positive pressure), zone 2 (Pa > PA > Pv), zone 3 (Pa > Pv > PA, base).","Zonas de West."],["1c85v58w2","What causes increased alveolar dead space?","Pulmonary embolism, low cardiac output, positive pressure ventilation.","Embolia e débito baixo."],["p52b0lr8m","What is shunt fraction normal value?","About 2-5% (bronchial and Thebesian veins).","2 a 5%."],["1f7eg1y1l","What are causes of intrapulmonary shunt?","Pneumonia, atelectasis, ARDS, pulmonary edema, AVMs.","Pneumonia, atelectasia, SDRA."],["1gs0hny1o","What is the effect of PEEP in ARDS?","Recruits collapsed alveoli, improving oxygenation (reduces shunt).","Recruta alvéolos."],["16i1mm3fg","What is the lung protective ventilation strategy in ARDS?","Low tidal volume (6 mL/kg ideal body weight), plateau pressure <30, adequate PEEP; prone positioning.","Volume corrente baixo."],["zt5mgvtv6","What is the PaO2/FiO2 ratio used for?","Severity of ARDS (mild ≤300, moderate ≤200, severe ≤100).","Gravidade da SDRA."],["qemv6g1b8","What happens to PaCO2 with doubling alveolar ventilation?","PaCO2 halves (inverse relationship).","CO2 cai pela metade."],["cvaa67czn","What is the effect of hyperventilation on cerebral blood flow?","Hypocapnia causes cerebral vasoconstriction, decreasing flow and ICP.","Reduz o fluxo cerebral."],["smea0r1dc","What is periodic breathing (Cheyne-Stokes)?","Cyclic crescendo-decrescendo breathing with apnea; heart failure, stroke, opioids, altitude.","Respiração de Cheyne-Stokes."],["1fvh0mh1y","What is Kussmaul breathing?","Deep rapid breathing in metabolic acidosis (DKA).","Respiração de Kussmaul."],["xxk0hhh8j","What is Biot (ataxic) breathing?","Irregular breathing with apnea from medullary damage.","Respiração atáxica."],["dxuk1dmsc","What is the treatment of hypoxemic respiratory failure vs hypercapnic?","Hypoxemic: oxygen, PEEP. Hypercapnic: increase ventilation (noninvasive positive pressure, intubation).","Oxigênio versus ventilação."],["1ke0ock1u","What is noninvasive positive pressure ventilation useful for?","COPD exacerbation with hypercapnia, cardiogenic pulmonary edema.","DPOC e edema pulmonar."],["r5py8vhf1","What is the role of CPAP in obstructive sleep apnea?","Keeps upper airway open during sleep.","Mantém a via aérea aberta."],["x5vxy7hdz","What is obesity hypoventilation syndrome?","BMI ≥30 with daytime hypercapnia (PaCO2 >45) not due to other causes (Pickwickian).","Hipoventilação por obesidade."],["jzy0mkazb","What are the consequences of obstructive sleep apnea?","Hypertension, pulmonary hypertension, arrhythmias, daytime somnolence, polycythemia, sudden death.","Hipertensão e sonolência."],["14kiddp1i","What is central sleep apnea?","Impaired respiratory effort from CNS injury, heart failure (Cheyne-Stokes), opioids.","Apneia central."],["5gtk08e8f","What is the response of ventilation to metabolic alkalosis?","Hypoventilation (limited by hypoxemia).","Hipoventilação."],["o4tph41o2","What is the effect of pregnancy on PaCO2?","Decreased PaCO2 (about 30 mmHg) from progesterone-driven hyperventilation.","CO2 cai."],["1laha7s1s","What is the role of the pleural space's lymphatics?","Drain pleural fluid; obstruction causes effusion.","Drenam o líquido pleural."],["26t8bcz4x","What are Light criteria for exudative effusion?","Pleural/serum protein >0.5, pleural/serum LDH >0.6, or pleural LDH >2/3 upper limit of normal serum LDH.","Critérios de Light."],["1o0le8u14","What causes transudative pleural effusion?","Heart failure (most common), nephrotic syndrome, cirrhosis (increased hydrostatic or decreased oncotic pressure).","Insuficiência cardíaca."],["r86ogpw2v","What causes exudative pleural effusion?","Infection (parapneumonic, TB), malignancy, PE, collagen vascular disease, pancreatitis.","Infecção, câncer, embolia."],["ps7bfiepv","What pleural fluid findings suggest complicated effusion or empyema?","pH <7.2, glucose <60, positive Gram stain, pus; needs drainage.","pH baixo e glicose baixa; drenar."],["11rjwuayc","What is a chylothorax?","Lymphatic fluid (high triglycerides, milky) from thoracic duct injury or lymphoma.","Linfa na pleura."],["1s7wt52dr","What is the physical exam of pleural effusion?","Dullness to percussion, decreased breath sounds, decreased tactile fremitus, tracheal deviation away if large.","Macicez e murmúrio reduzido."],["kz99o7w7w","What is the physical exam of consolidation (pneumonia)?","Dullness, bronchial breath sounds, increased fremitus, egophony, crackles.","Frêmito aumentado e egofonia."],["1900eis14","What is the physical exam of simple pneumothorax?","Hyperresonance, decreased breath sounds, decreased fremitus.","Hipertimpanismo."],["blckry1wr","What is the physical exam of tension pneumothorax?","Hyperresonance, absent breath sounds, tracheal deviation away, hypotension, JVD.","Desvio da traqueia e hipotensão."],["iqrewocdp","What is the physical exam of atelectasis?","Dullness, decreased breath sounds and fremitus, tracheal deviation toward the lesion.","Traqueia desvia para a lesão."],["im6kstzbp","What is the physical exam of emphysema?","Hyperresonance, decreased breath sounds, prolonged expiration, barrel chest.","Tórax em barril."],["1r1jhri1t","What is the treatment of tension pneumothorax?","Immediate needle decompression then chest tube.","Descompressão com agulha."],["w6vufb3ze","What is primary spontaneous pneumothorax?","Rupture of apical subpleural blebs in tall thin young men, smokers.","Rapaz alto e magro."],["17w7vld1h","What is secondary spontaneous pneumothorax?","From underlying lung disease (COPD, CF, Pneumocystis, Marfan).","Doença pulmonar de base."],["1hnmac81x","What is the treatment of a small primary pneumothorax?","Observation and supplemental oxygen; aspiration or chest tube if large.","Observação."],["1oucd1z1m","What is the effect of oxygen therapy on pneumothorax resolution?","Speeds resorption (nitrogen washout).","Acelera a reabsorção."],["w92mv81rm","What are the causes of digital clubbing?","Lung cancer, bronchiectasis, CF, interstitial lung disease, cyanotic heart disease, IBD, cirrhosis; not COPD alone.","Câncer de pulmão e bronquiectasia."],["1ohuf5119","What is the role of incentive spirometry postoperatively?","Prevents atelectasis.","Previne atelectasia."],["1nt892x12","What is the most common cause of postoperative fever in the first 24 hours (classically taught)?","Atelectasis (though evidence is weak).","Atelectasia."],["kfyaft1yj","What is the normal FEV1/FVC ratio?","About 0.8 (70-80%); <0.7 indicates obstruction.","Cerca de 0,8."],["1yu8i9o1x","What is peak expiratory flow used for?","Monitoring asthma control at home.","Monitorar a asma."],["1bjdkv11l","What is the effect of age on lung function?","Increased compliance, decreased recoil, increased RV and A-a gradient, decreased FEV1 and VC; TLC unchanged.","Envelhecimento pulmonar."],["t6jx0ng3t","What is the effect of kyphoscoliosis on lung function?","Restrictive pattern with normal DLCO.","Restrição com difusão normal."],["blcgjw1ii","What is the role of the diaphragm in ventilation?","Main inspiratory muscle; contraction increases thoracic volume and decreases intrapleural pressure.","Principal músculo inspiratório."],["t0xdg62zq","What is the effect of bilateral diaphragm paralysis?","Orthopnea and paradoxical abdominal movement; restrictive pattern.","Ortopneia."],["poq3lv1lh","What is the transpulmonary pressure?","Alveolar pressure minus intrapleural pressure; distends the lung.","Pressão transpulmonar."],["uxyp0k1xn","What is the effect of breath holding on PaCO2?","Increases PaCO2 (stimulates breathing via central chemoreceptors).","CO2 sobe."],["hkkeimoq3","What is the effect of carbon monoxide on the O2 dissociation curve?","Left shift and decreased O2-carrying capacity.","Desvio à esquerda."],["13e3m941f","What is the half-life of carboxyhemoglobin on room air vs 100% O2?","About 4-6 hours on room air; about 60-90 minutes on 100% O2; shorter with hyperbaric oxygen.","Oxigênio encurta a meia-vida."],["1olgvjs1q","What is the pulse oximetry limitation in methemoglobinemia?","Saturation reads about 85% regardless of true PaO2.","Satura em torno de 85%."],["q11grujng","What is the cause of cyanosis unresponsive to oxygen with chocolate blood?","Methemoglobinemia.","Metemoglobinemia."],["o7lg1t19t","What is the relationship between hematocrit and pulmonary vascular resistance?","Increased hematocrit increases viscosity and resistance.","Hematócrito alto aumenta resistência."],["177o6mv13","What is the effect of lung transplant on cough reflex?","Denervated lung loses cough reflex below the anastomosis, increasing infection risk.","Perde o reflexo da tosse."]]}];
